import java.util.*;
import java.io.*;

public class Main {
    static String[] nearestCities(String[] names, long[] xs, long[] ys, String[] queries) {
        // Write your solution here
        return new String[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] names = new String[n];
        long[] xs = new long[n], ys = new long[n];
        for (int i = 0; i < n; i++) {
            names[i] = st.nextToken();
            xs[i] = Long.parseLong(st.nextToken());
            ys[i] = Long.parseLong(st.nextToken());
        }
        int m = Integer.parseInt(st.nextToken());
        String[] queries = new String[m];
        for (int i = 0; i < m; i++) queries[i] = st.nextToken();
        String[] res = nearestCities(names, xs, ys, queries);
        StringBuilder sb = new StringBuilder();
        for (String s : res) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
